import { getCrossPlatformPathRegex } from "utils/regex.js";
import { createPatchCode } from "../astCodePatcher.js";
import type { CodePatcher } from "../codePatcher.js";

// Stale entries are regenerated by the revalidation queue, so the check that lets Next.js
// regenerate them in the background is replaced by `true`.
// The variables were renamed across versions and are minified in the runtime bundles.
export const rule = `
rule:
  pattern: "!$ENTRY.isStale || $CONTEXT.isPrefetch"
fix:
  'true'`;

// Since Next 15, route modules run from the compiled runtime bundles, which have their own copy
// of the response cache.
export const pathFilter = getCrossPlatformPathRegex(
  String.raw`(server/response-cache/index\.js|compiled/next-server/[\w-]+\.runtime\.prod\.js)$`,
  { escape: false },
);

export const patchBackgroundRevalidation = {
  name: "patchBackgroundRevalidation",
  patches: [
    {
      // TODO: test for earlier versions of Next
      versions: ">=14.1.0",
      pathFilter,
      contentFilter: /\.isPrefetch/,
      patchCode: createPatchCode(rule),
    },
  ],
} satisfies CodePatcher;
